import{At as e,Mt as t,Qt as n,lt as r}from"./chunks/framework.DwOUwJQP.js";var i=JSON.parse(`{"title":"区块链基础知识","description":"","frontmatter":{"title":"区块链基础知识","date":"2025-02-08T00:00:00.000Z","tags":["web3"]},"headers":[],"relativePath":"blogs/other/web3/区块链基础知识.md","filePath":"blogs/other/web3/区块链基础知识.md","lastUpdated":1788090369000}`),a={name:`blogs/other/web3/区块链基础知识.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h3 id="交易-transactions" tabindex="-1">交易 transactions <a class="header-anchor" href="#交易-transactions" aria-label="Permalink to “交易 transactions”">​</a></h3><p>区块链是一个全球共享的事务数据库。这意味着每个人只要参与网络就可以读取数据库中的条目。如果你想更改数据库中的某些内容，你必须创建一个所谓的交易，该交易必须得到所有其他人的接受。交易一词意味着你想要进行的更改（假设你想同时更改两个值）要么根本没有完成，要么完全应用。此外，当你的事务被应用到数据库时，其他任何事务都无法更改它。</p><h3 id="区块-blocks" tabindex="-1">区块 blocks <a class="header-anchor" href="#区块-blocks" aria-label="Permalink to “区块 blocks”">​</a></h3><p>需要克服的一个主要障碍是所谓的“双重支付攻击”（用比特币术语来说）：如果网络中存在两笔交易，它们都想清空一个账户，会发生什么？只有一笔交易是有效的，通常是先被接受的交易。问题是，“先”在对等网络中不是一个客观术语。</p><p>对此的抽象回答是，您不必关心。系统会为您选择一个全球接受的交易顺序，从而解决冲突。交易将被捆绑到所谓的“区块”中，然后在所有参与节点之间执行和分发。如果两笔交易相互矛盾，那么最终排名第二的交易将被拒绝，并且不会成为区块的一部分。</p><p>这些区块在时间上形成线性序列，这就是“区块链”一词的由来。区块会定期添加到链中，尽管这些间隔将来可能会发生变化。</p><p>作为“顺序选择机制”的一部分，即所谓的<a href="https://ethereum.org/en/developers/docs/consensus-mechanisms/pos/attestations/" target="_blank" rel="noreferrer">证明</a>，可能会发生区块不时被撤销的情况，但仅限于链的“顶端”。在特定区块顶部添加的区块越多，该区块被撤销的可能性就越小。因此，您的交易可能会被撤销，甚至从区块链中删除，但您等待的时间越长，这种可能性就越小。</p><blockquote><p>交易不能保证一定会被包含在下一个区块或任何特定的未来区块中，因为交易被包含在哪个区块中并不由交易的提交者决定，而是由矿工决定。</p></blockquote><h3 id="常见单位换算" tabindex="-1"><strong>常见单位换算</strong> <a class="header-anchor" href="#常见单位换算" aria-label="Permalink to “常见单位换算”">​</a></h3><blockquote><p>以太坊的最小单位是 <strong>Wei</strong>，1 ETH 被拆分成 <strong>10¹⁸</strong> 个 Wei，就像 <strong>1 元 = 100 分</strong> 一样。</p><p>💡 <strong>Gwei（10⁹ Wei）是 Gas 费计算的常用单位</strong>，比如</p></blockquote><div class="language-solidity"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gasPrice </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> gwei</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// 50 Gwei</span></span></code></pre></div><table tabindex="0"><thead><tr><th><strong>单位</strong></th><th><strong>换算关系</strong></th><th><strong>示例</strong></th></tr></thead><tbody><tr><td><strong>Wei</strong></td><td>1 Wei = 1</td><td><code>1 wei</code></td></tr><tr><td><strong>Kwei</strong></td><td>1 Kwei = 10³ Wei</td><td><code>1000 wei</code></td></tr><tr><td><strong>Mwei</strong></td><td>1 Mwei = 10⁶ Wei</td><td><code>1_000_000 wei</code></td></tr><tr><td><strong>Gwei</strong></td><td>1 Gwei = 10⁹ Wei</td><td><code>1_000_000_000 wei</code></td></tr><tr><td><strong>Szabo</strong></td><td>1 Szabo = 10¹² Wei</td><td><code>1_000_000_000_000 wei</code></td></tr><tr><td><strong>Finney</strong></td><td>1 Finney = 10¹⁵ Wei</td><td><code>1_000_000_000_000_000 wei</code></td></tr><tr><td><strong>Ether</strong></td><td>1 Ether = 10¹⁸ Wei</td><td><code>1_000_000_000_000_000_000 wei</code></td></tr></tbody></table>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};